            ('turhautuneeksi ristiriitaisista neuvoista', 'frustrirani zaradi nasprotujočih si nasvetov'),
            ('uupuneeksi joka kerta, kun sinun täytyy laittaa ruokaa', 'preobremenjeni vsakič, ko morate kuhati'),
            ('tai huolestuneeksi siitä, että tilanne pahenee, ellet toimi', 'ali vas skrbi, da se bodo stvari poslabšale, če ne ukrepate'),
            @('Tämä paketti on luotu <strong>juuri sinulle</strong>.', 'Ta paket je bil ustvarjen za vas.'),
            @('Sinun ei tarvitse olla täydellinen.', 'Ni vam treba biti popolni.'),
            @('Et tarvitse äärimmäisyyksiä.', 'Ne potrebujete ekstremov.'),
            @('Tarvitset vain selkeän ja sopivan suunnitelman, joka sopii todelliseen elämään.', 'Potrebujete le jasen in prilagojen načrt, ki se prilega resničnemu življenju.'),
