# Run loop to generate pages
foreach ($lang_name in $translations.Keys) {
    $details = $translations[$lang_name]
    $lang_code = $details.lang
    $suffix = $details.suffix
    $title = $details.title
    
    $content = $template_content
    
    # Replace global structural details
    $content = $content.Replace('lang="fi"', "lang=""$lang_code""")
    $content = $content.Replace('document.title = "Rasvamaksa – Atlas Library";', "document.title = ""$title – Atlas Library"";")
    $content = $content.Replace('<title>Rasvamaksa – Atlas Library</title>', "<title>$title – Atlas Library</title>")
    
    # Replace image paths to point to correct multilingual formats
    $content = $content.Replace("gordura_IMAGEM1_FI.png", "gordura_IMAGEM1_$suffix.png")
    $content = $content.Replace("gordura_IMAGEM2_FI.png", "gordura_IMAGEM2_$suffix.png")
    $content = $content.Replace("gordura_IMAGEM3_FI.jpg", "gordura_IMAGEM3_$suffix.jpg")
    $content = $content.Replace("gordura_IMAGEM4_FI.jpg", "gordura_IMAGEM4_$suffix.jpg")
    $content = $content.Replace("gordura_IMAGEM5_FI.png", "gordura_IMAGEM5_$suffix.png")
    for ($i = 1; $i -le 4; $i++) {
        $content = $content.Replace("gordura_$i`_FI.jpg", "gordura_$i`_$suffix.jpg")
    }
    
    # Replace checkout prefix locale from '/fi/cart/' to '/[lang]/cart/'
    $content = $content.Replace("/fi/cart/", "/$lang_code/cart/")
    
    # Replace texts from the language-specific mapping (sorted by length descending to prevent substring collisions)
    $sorted_replacements = $details.replacements | Sort-Object { $_[0].Length } -Descending
    foreach ($replacement in $sorted_replacements) {
        $fi_text = $replacement[0]
        $target_text = $replacement[1]
        $content = $content.Replace($fi_text, $target_text)
    }
    
    # Destination directory and file
    $dest_dir = Join-Path $base_dir "gorduranofigado$lang_name`shopify"
    if (-not (Test-Path $dest_dir)) {
        New-Item -ItemType Directory -Path $dest_dir -Force | Out-Null
        Write-Host "Created directory: $dest_dir"
    }
    
    $dest_file = Join-Path $dest_dir "index.html"
    [System.IO.File]::WriteAllText($dest_file, $content, [System.Text.Encoding]::UTF8)
    Write-Host "Written file: $dest_file"
}

Write-Host "Multilingual landing page batch generation complete!"
